using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionAreaCompanionOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionAreaCompanion Omen Logic")]
public class BattleActionAreaCompanionOmenLogic : OmenLogic
{
	[Header("Enemies")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		List<GameObject> activeCompanions = currentCompanions.ActiveCompanions;
		battleAction.AreaCastTargetAmount(activeCompanions, actionValue, source);
	}
}
